package com.gerenciadorrural.modules.finance.infrastructure;
import com.fasterxml.jackson.databind.ObjectMapper; import com.gerenciadorrural.modules.finance.domain.*; import com.gerenciadorrural.shared.tenancy.TenantId; import org.springframework.jdbc.core.namedparam.*; import org.springframework.stereotype.Repository; import java.sql.*; import java.time.*; import java.util.*; import static com.gerenciadorrural.modules.finance.domain.FinanceModels.*;
@Repository public class JdbcFinanceRepository implements FinanceRepository {private final NamedParameterJdbcTemplate j;private final ObjectMapper json;public JdbcFinanceRepository(NamedParameterJdbcTemplate j,ObjectMapper json){this.j=j;this.json=json;}private MapSqlParameterSource p(TenantId t){return new MapSqlParameterSource("t",t.value());}
 public Optional<Category> category(TenantId t,UUID id,boolean lock){return j.query("select * from app.financial_categories where tenant_id=:t and id=:id"+(lock?" for update":""),p(t).addValue("id",id),(r,n)->category(r)).stream().findFirst();}public Category insertCategory(TenantId t,Category x){j.update("insert into app.financial_categories(id,tenant_id,name,code,kind,status)values(:id,:t,:n,:c,:k,:s)",p(t).addValue("id",x.id()).addValue("n",x.name()).addValue("c",x.code()).addValue("k",x.kind().name()).addValue("s",x.status().name()));return category(t,x.id(),false).orElseThrow();}public Category updateCategory(TenantId t,Category x,long v){if(j.update("update app.financial_categories set name=:n,code=:c,kind=:k,status=:s,version=version+1,updated_at=current_timestamp where tenant_id=:t and id=:id and version=:v",p(t).addValue("id",x.id()).addValue("n",x.name()).addValue("c",x.code()).addValue("k",x.kind().name()).addValue("s",x.status().name()).addValue("v",v))==0)throw new com.gerenciadorrural.modules.finance.application.FinanceService.Conflict();return category(t,x.id(),false).orElseThrow();}public List<Category> categories(TenantId t){return j.query("select * from app.financial_categories where tenant_id=:t order by name,id",p(t),(r,n)->category(r));}
 public Optional<Entry> entry(TenantId t,UUID f,UUID id,boolean lock){return j.query("select e.*,c.kind category_kind from app.financial_entries e join app.financial_categories c on c.tenant_id=e.tenant_id and c.id=e.category_id where e.tenant_id=:t and e.farm_id=:f and e.id=:id"+(lock?" for update":""),p(t).addValue("f",f).addValue("id",id),(r,n)->entry(r)).stream().findFirst();}public Optional<Entry> entryByOperation(TenantId t,UUID f,UUID o){return j.query("select e.*,c.kind category_kind from app.financial_entries e join app.financial_categories c on c.tenant_id=e.tenant_id and c.id=e.category_id where e.tenant_id=:t and e.farm_id=:f and e.operation_id=:o",p(t).addValue("f",f).addValue("o",o),(r,n)->entry(r)).stream().findFirst();}public Entry insertEntry(TenantId t,UUID f,Entry x,UUID u){j.update("insert into app.financial_entries(id,tenant_id,farm_id,operation_id,type,status,category_id,category_name_snapshot,description,amount,due_on,notes,created_by_user_id,updated_by_user_id)values(:id,:t,:f,:o,:type,:status,:c,:cn,:d,:a,:due,:n,:u,:u)",p(t).addValue("f",f).addValue("id",x.id()).addValue("o",x.operationId()).addValue("type",x.type().name()).addValue("status",x.status().name()).addValue("c",x.category().id()).addValue("cn",x.category().name()).addValue("d",x.description()).addValue("a",x.amount()).addValue("due",x.dueOn()).addValue("n",x.notes()).addValue("u",u));return entry(t,f,x.id(),false).orElseThrow();}public Entry updateEntry(TenantId t,UUID f,Entry x,long v,UUID u){if(j.update("update app.financial_entries set status=:s,category_id=:c,category_name_snapshot=:cn,description=:d,amount=:a,due_on=:due,settled_on=:settled,cancelled_at=case when :s='CANCELLED' then current_timestamp else null end,notes=:n,version=version+1,updated_by_user_id=:u,updated_at=current_timestamp where tenant_id=:t and farm_id=:f and id=:id and version=:v",p(t).addValue("f",f).addValue("id",x.id()).addValue("s",x.status().name()).addValue("c",x.category().id()).addValue("cn",x.category().name()).addValue("d",x.description()).addValue("a",x.amount()).addValue("due",x.dueOn()).addValue("settled",x.settledOn()).addValue("n",x.notes()).addValue("u",u).addValue("v",v))==0)throw new com.gerenciadorrural.modules.finance.application.FinanceService.Conflict();return entry(t,f,x.id(),false).orElseThrow();}
 public void event(TenantId t,UUID f,UUID e,UUID o,EventType y,UUID a,LocalDate day,Object details){try{j.update("insert into app.financial_entry_events(id,tenant_id,farm_id,entry_id,operation_id,event_type,actor_user_id,occurred_on,details)values(:id,:t,:f,:e,:o,:y,:a,:d,cast(:x as jsonb))",p(t).addValue("f",f).addValue("id",UUID.randomUUID()).addValue("e",e).addValue("o",o).addValue("y",y.name()).addValue("a",a).addValue("d",day).addValue("x",json.writeValueAsString(details)));}catch(Exception ex){throw new IllegalStateException(ex);}}public Optional<Event> eventByOperation(TenantId t,UUID f,UUID e,UUID o){return j.query("select * from app.financial_entry_events where tenant_id=:t and farm_id=:f and entry_id=:e and operation_id=:o",p(t).addValue("f",f).addValue("e",e).addValue("o",o),(r,n)->event(r)).stream().findFirst();}public List<Event> history(TenantId t,UUID f,UUID e){return j.query("select * from app.financial_entry_events where tenant_id=:t and farm_id=:f and entry_id=:e order by recorded_at desc,id desc",p(t).addValue("f",f).addValue("e",e),(r,n)->event(r));}
 public List<Entry> entries(TenantId t,UUID f,EntryType y,EntryStatus s,UUID c,LocalDate from,LocalDate to,String q,int z,long off){return j.query("select e.*,fc.kind category_kind from app.financial_entries e join app.financial_categories fc on fc.tenant_id=e.tenant_id and fc.id=e.category_id where e.tenant_id=:t and e.farm_id=:f and (:y is null or e.type=:y) and (:s is null or e.status=:s) and (:c is null or e.category_id=:c) and (:from is null or e.due_on>=:from) and (:to is null or e.due_on<=:to) and (:q is null or lower(e.description) like lower(:q) escape '\\') order by e.due_on,e.id limit :z offset :off",p(t).addValue("f",f).addValue("y",y==null?null:y.name()).addValue("s",s==null?null:s.name()).addValue("c",c).addValue("from",from).addValue("to",to).addValue("q",q==null?null:"%"+q.replace("%","\\%").replace("_","\\_")+"%").addValue("z",z).addValue("off",off),(r,n)->entry(r));}public long count(TenantId t,UUID f,EntryType y,EntryStatus s,UUID c,LocalDate from,LocalDate to,String q){return entries(t,f,y,s,c,from,to,q,100001,0).size();}
 public Summary summary(TenantId t,UUID f,UUID c,LocalDate from,LocalDate to,LocalDate today){return j.queryForObject("select coalesce(sum(amount)filter(where status='PENDING' and type='INCOME'),0) pi,coalesce(sum(amount)filter(where status='PENDING' and type='EXPENSE'),0) pe,coalesce(sum(amount)filter(where status='SETTLED' and type='INCOME'),0) si,coalesce(sum(amount)filter(where status='SETTLED' and type='EXPENSE'),0) se,coalesce(sum(amount)filter(where status='PENDING' and type='INCOME' and due_on<:today),0) oi,coalesce(sum(amount)filter(where status='PENDING' and type='EXPENSE' and due_on<:today),0) oe from app.financial_entries where tenant_id=:t and farm_id=:f and (:c is null or category_id=:c) and due_on between :from and :to",p(t).addValue("f",f).addValue("c",c).addValue("from",from).addValue("to",to).addValue("today",today),(r,n)->new Summary(r.getBigDecimal("pi"),r.getBigDecimal("pe"),r.getBigDecimal("si"),r.getBigDecimal("se"),r.getBigDecimal("si").subtract(r.getBigDecimal("se")),r.getBigDecimal("oi"),r.getBigDecimal("oe")));}
 public List<CategoryTotals> categoryTotals(TenantId t,UUID f,LocalDate from,LocalDate to){return j.query("select e.category_id,e.category_name_snapshot,fc.kind,coalesce(sum(amount)filter(where status='SETTLED' and type='INCOME'),0) si,coalesce(sum(amount)filter(where status='SETTLED' and type='EXPENSE'),0) se,coalesce(sum(amount)filter(where status='PENDING' and type='INCOME'),0) pi,coalesce(sum(amount)filter(where status='PENDING' and type='EXPENSE'),0) pe from app.financial_entries e join app.financial_categories fc on fc.tenant_id=e.tenant_id and fc.id=e.category_id where e.tenant_id=:t and e.farm_id=:f and e.due_on between :from and :to group by e.category_id,e.category_name_snapshot,fc.kind order by e.category_name_snapshot,e.category_id",p(t).addValue("f",f).addValue("from",from).addValue("to",to),(r,n)->new CategoryTotals(new CategorySummary(r.getObject(1,UUID.class),r.getString(2),CategoryKind.valueOf(r.getString(3))),r.getBigDecimal(4),r.getBigDecimal(5),r.getBigDecimal(6),r.getBigDecimal(7)));}
 private static Category category(ResultSet r)throws SQLException{return new Category(r.getObject("id",UUID.class),r.getString("name"),r.getString("code"),CategoryKind.valueOf(r.getString("kind")),CategoryStatus.valueOf(r.getString("status")),r.getLong("version"),r.getObject("created_at",OffsetDateTime.class).toInstant(),r.getObject("updated_at",OffsetDateTime.class).toInstant());}private static Entry entry(ResultSet r)throws SQLException{return new Entry(r.getObject("id",UUID.class),r.getObject("operation_id",UUID.class),EntryType.valueOf(r.getString("type")),EntryStatus.valueOf(r.getString("status")),new CategorySummary(r.getObject("category_id",UUID.class),r.getString("category_name_snapshot"),CategoryKind.valueOf(r.getString("category_kind"))),r.getString("description"),r.getBigDecimal("amount"),r.getObject("due_on",LocalDate.class),r.getObject("settled_on",LocalDate.class),r.getString("notes"),r.getLong("version"),r.getObject("created_at",OffsetDateTime.class).toInstant(),r.getObject("updated_at",OffsetDateTime.class).toInstant());}private Event event(ResultSet r)throws SQLException{try{return new Event(r.getObject("id",UUID.class),r.getObject("operation_id",UUID.class),EventType.valueOf(r.getString("event_type")),r.getObject("actor_user_id",UUID.class),r.getObject("occurred_on",LocalDate.class),json.readTree(r.getString("details")),r.getObject("recorded_at",OffsetDateTime.class).toInstant());}catch(Exception x){throw new SQLException(x);}}}
